function run(body) {
  try {
    return new Function(body)();
  } catch (error) {
    return error.name;
  }
}

console.log(run('stock = 4; return stock;'));
console.log(run('"use strict"; items = 4; return items;'));
console.log(run('let n = 1; "use strict"; left = n; return left;'));
console.log(run("class Shop { open() { doors = 2; } } new Shop().open(); return doors;"));
